"""Resource planning service — illustrative estimates only."""


RESOURCE_METHODOLOGY = (
    "Resources are estimated using a simple illustrative formula: "
    "base_count = crowd_size / divisor × risk_multiplier, where the divisor "
    "varies by resource type and the risk multiplier scales with risk level. "
    "These estimates are for demonstration purposes only."
)

RESOURCE_DISCLAIMER = (
    "These resource estimates are illustrative only and generated by a simplified "
    "planning model for educational demonstration. They do not represent validated "
    "emergency-response standards. Actual resource deployment must follow approved "
    "plans, local regulations, and qualified human review. This application does not "
    "dispatch personnel or emergency services."
)

RISK_MULTIPLIERS = {
    "Low": 0.65,
    "Medium": 0.85,
    "High": 1.15,
    "Critical": 1.40,
}

# Resource divisors: crowd_size / divisor × multiplier = recommended count
RESOURCE_DIVISORS = {
    "security_personnel": 500,
    "police_units": 1800,
    "medical_teams": 3500,
    "ambulances": 5000,
}

RESOURCE_MINIMUMS = {
    "security_personnel": 2,
    "police_units": 1,
    "medical_teams": 1,
    "ambulances": 1,
}


def calculate_resources(
    risk_level: str,
    crowd_size: int,
    venue_capacity: int | None = None,
) -> dict:
    """Calculate illustrative resource estimates.

    Args:
        risk_level: One of Low, Medium, High, Critical.
        crowd_size: Expected crowd size.
        venue_capacity: Venue capacity (reserved for future formulas).

    Returns:
        dict with resource counts, multiplier, methodology, and disclaimer.
    """
    multiplier = RISK_MULTIPLIERS.get(risk_level, 1.0)

    resources = {}
    for resource, divisor in RESOURCE_DIVISORS.items():
        minimum = RESOURCE_MINIMUMS[resource]
        resources[resource] = max(minimum, round(crowd_size / divisor * multiplier))

    return {
        "resources": resources,
        "multiplier": multiplier,
        "methodology": RESOURCE_METHODOLOGY,
        "disclaimer": RESOURCE_DISCLAIMER,
    }

